  'ui.tooling_rule_off': 'Désactivé : ignore le nombre d\'outils',
  'ui.tooling_rule_hard': 'Strict : respecter les exemplaires libres',
  'ui.tooling_rule_help': 'Tool 1 et Tool 2 sont les identifiants d\'outil de chaque commande. Un outil est un type dont l\'usine possède plusieurs exemplaires interchangeables ; les quantités se trouvent dans Données de base: Inventaire des outils. Les exemplaires disponibles sont le total moins ceux hors service, et un outil sans ligne compte pour 1 exemplaire.',
  'ui.tooling_rule_help_detail': 'Désactivé : l\'optimiseur ignore le nombre d\'outils, mais l\'alerte du Gantt reste active. Strict : après le placement, une commande qui exige plus d\'exemplaires que ceux disponibles est déplacée dans un créneau libre de sa machine ou envoyée à À planifier avec le motif Conflit d\'outil. Les commandes gelées, fermes et en cours ne sont jamais déplacées, et les conflits existants restent des alertes. Effet à la prochaine optimisation ; en revenant à Désactivé, les anciens motifs de conflit d\'outil restent jusqu\'à la prochaine exécution. Retirer le retard et le placement manuel ignorent cette règle.',
  'ui.tooling_rule_hint': 'Effet à la prochaine optimisation. Les commandes gelées, fermes et en cours ne sont pas déplacées.',
